// producer
lock(mutex);
while (buffer is full) wait(notFull, mutex);
add item to buffer;
signal(notEmpty);
unlock(mutex);

// consumer
lock(mutex);
while (buffer is empty) wait(notEmpty, mutex);
remove item from buffer;
signal(notFull);
unlock(mutex);

